L = os.path.dirname(os.path.abspath(__file__)) + "/locales/"
for lc, data in D.items():
    out = {}
    for section, keys in BASE.items():
        out[section] = dict(keys)
        for key in keys:
            val = data.get(section, {}).get(key, "")
            if val:
                out[section][key] = val
    path = L + lc + ".json"
    with open(path, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
        f.write("\n")

print(f"Generated {len(D)} locale files")

# 验证
for lc in D:
    p = L + lc + ".json"
    with open(p) as f:
        j = json.load(f)
    assert j["commands"]["title"], f"Missing commands.title in {lc}"
print("All files valid")